import{_ as t,o as e,c as a,Q as d}from"./chunks/framework.48927342.js";const g=JSON.parse('{"title":"Bus Driver Job Application","description":"","frontmatter":{},"headers":[],"relativePath":"en/more/maltese/practice/emails/09-bus-driver-job-application.md","filePath":"en/more/maltese/practice/emails/09-bus-driver-job-application.md"}'),r={name:"en/more/maltese/practice/emails/09-bus-driver-job-application.md"},o=d('<h1 id="bus-driver-job-application" tabindex="-1">Bus Driver Job Application <a class="header-anchor" href="#bus-driver-job-application" aria-label="Permalink to &quot;Bus Driver Job Application&quot;">​</a></h1><p><strong>Scenario:</strong> The applicant writes to the bus company to apply for the position of bus driver.</p><h2 id="email-header" tabindex="-1">Email Header <a class="header-anchor" href="#email-header" aria-label="Permalink to &quot;Email Header&quot;">​</a></h2><p><strong>Lil (To):</strong> <a href="mailto:info@transport.com" target="_blank" rel="noreferrer">info@transport.com</a><strong>Mingħand (From):</strong> [isem]@email.com <strong>Data (Date):</strong> 15 ta&#39; Ottubru 2026 <strong>Suġġett (Subject):</strong> Applikazzjoni ta&#39; xogħol ta&#39; sewwieq tal-karozza tal-linja</p><h2 id="full-email" tabindex="-1">Full Email <a class="header-anchor" href="#full-email" aria-label="Permalink to &quot;Full Email&quot;">​</a></h2><blockquote><p><strong>Lil:</strong> <a href="mailto:info@transport.com" target="_blank" rel="noreferrer">info@transport.com</a><strong>Mingħand:</strong> [isem]@email.com <strong>Data:</strong> 15 ta&#39; Ottubru 2026 <strong>Suġġett:</strong> Applikazzjoni ta&#39; xogħol ta&#39; sewwieq tal-karozza tal-linja</p><p>Għażiż Sinjur / Sinjura,</p><p>Qed nikteb biex napplika għall-impjieg ta&#39; sewwieq tal-karozza tal-linja.</p><p>Għandi liċenzja tas-sewqan tal-kategorija D.</p><p>Għandi esperjenza ta&#39; tliet snin bħala sewwieq tal-karozza tal-linja.</p><p>Naf it-toroq ta&#39; Malta tajjeb ħafna.</p><p>Jien responsabbli u jimpurtani mis-sigurtà tal-passiġġieri.</p><p>Ninsab kalm u paċenzjuż mat-traffiku.</p><p>Nirrispetta r-regoli tat-triq u nżomm il-ħin.</p><p>Nispera li nisma&#39; mingħandkom dalwaqt.</p><p>Grazzi talli qiesu l-applikazzjoni tiegħi.</p><p>Tislijiet, [Ismek]</p></blockquote><h2 id="sentence-by-sentence-translation-and-word-notes" tabindex="-1">Sentence-by-Sentence Translation and Word Notes <a class="header-anchor" href="#sentence-by-sentence-translation-and-word-notes" aria-label="Permalink to &quot;Sentence-by-Sentence Translation and Word Notes&quot;">​</a></h2><p><strong>Malti:</strong> Lil: <a href="mailto:info@transport.com" target="_blank" rel="noreferrer">info@transport.com</a></p><p><strong>Translation:</strong> To: <a href="mailto:info@transport.com" target="_blank" rel="noreferrer">info@transport.com</a></p><table><thead><tr><th>Maltese</th><th>English meaning</th><th>Notes</th></tr></thead><tbody><tr><td>Lil</td><td>to; recipient</td><td>Maltese label for the email &quot;To&quot; field</td></tr><tr><td><a href="mailto:info@transport.com" target="_blank" rel="noreferrer">info@transport.com</a></td><td>email address</td><td>The bus company&#39;s recruitment email (example)</td></tr></tbody></table><p><strong>Malti:</strong> Mingħand: [isem]@email.com</p><p><strong>Translation:</strong> From: [your name]@email.com</p><table><thead><tr><th>Maltese</th><th>English meaning</th><th>Notes</th></tr></thead><tbody><tr><td>Mingħand</td><td>from; sender</td><td>Maltese label for the email &quot;From&quot; field; literally &quot;from ...&quot;</td></tr><tr><td>[isem]@email.com</td><td>email address</td><td>Placeholder for your email; replace with your real one</td></tr></tbody></table><p><strong>Malti:</strong> Data: 15 ta&#39; Ottubru 2026</p><p><strong>Translation:</strong> Date: 15 October 2026</p><table><thead><tr><th>Maltese</th><th>English meaning</th><th>Notes</th></tr></thead><tbody><tr><td>Data</td><td>date</td><td>Email &quot;Date&quot; field; Maltese date format is &quot;day ta&#39; month year&quot;</td></tr><tr><td>15</td><td>fifteen</td><td>Day in the date</td></tr><tr><td>ta&#39;</td><td>of</td><td>Links the day and the month</td></tr><tr><td>Ottubru</td><td>October</td><td>Month name</td></tr></tbody></table><p><strong>Malti:</strong> Suġġett: Applikazzjoni ta&#39; xogħol ta&#39; sewwieq tal-karozza tal-linja</p><p><strong>Translation:</strong> Subject: Application for the Position of Bus Driver</p><table><thead><tr><th>Maltese</th><th>English meaning</th><th>Notes</th></tr></thead><tbody><tr><td>Suġġett</td><td>subject</td><td>Email &quot;Subject&quot; field</td></tr><tr><td>Applikazzjoni</td><td>application</td><td>Feminine loanword from application</td></tr><tr><td>ta&#39;</td><td>of</td><td>Possession linker</td></tr><tr><td>xogħol</td><td>work; job</td><td>Masculine noun</td></tr><tr><td>ta&#39;</td><td>of</td><td>Possession linker</td></tr><tr><td>sewwieq</td><td>driver</td><td>Masculine noun</td></tr><tr><td>tal-karozza</td><td>of the car</td><td>Contracted <code>ta&#39;</code> + <code>il-karozza</code></td></tr><tr><td>tal-linja</td><td>of the line</td><td>Contracted <code>ta&#39;</code> + <code>il-linja</code>; together &quot;the bus&quot;</td></tr></tbody></table><p><strong>Malti:</strong> Għażiż Sinjur / Sinjura,</p><p><strong>Translation:</strong> Dear Sir / Madam,</p><table><thead><tr><th>Maltese</th><th>English meaning</th><th>Notes</th></tr></thead><tbody><tr><td>Għażiż</td><td>dear</td><td>Masculine singular form</td></tr><tr><td>Sinjur</td><td>sir; Mr.</td><td>Masculine noun</td></tr><tr><td>/</td><td>or</td><td>Indicates a choice between two</td></tr><tr><td>Sinjura</td><td>madam; Mrs.</td><td>Feminine noun</td></tr></tbody></table><h3 id="_1" tabindex="-1">1. <a class="header-anchor" href="#_1" aria-label="Permalink to &quot;1.&quot;">​</a></h3><p><strong>Malti:</strong> Qed nikteb biex napplika għall-impjieg ta&#39; sewwieq tal-karozza tal-linja.</p><p><strong>Translation:</strong> I am writing to apply for the position of bus driver.</p><table><thead><tr><th>Maltese</th><th>English meaning</th><th>Notes</th></tr></thead><tbody><tr><td>Qed</td><td>am (progressive marker)</td><td>Used with a verb to indicate an ongoing action</td></tr><tr><td>nikteb</td><td>I write</td><td>First-person singular present</td></tr><tr><td>biex</td><td>in order to</td><td>Introduces a purpose clause</td></tr><tr><td>napplika</td><td>I apply</td><td>First-person singular form, loanword from apply</td></tr><tr><td>għall-impjieg</td><td>for the job</td><td>Contracted <code>għal</code> + <code>l-impjieg</code></td></tr><tr><td>ta&#39;</td><td>of</td><td>Possession linker</td></tr><tr><td>sewwieq</td><td>driver</td><td>Masculine noun</td></tr><tr><td>tal-karozza</td><td>of the car</td><td>Contracted <code>ta&#39;</code> + <code>il-karozza</code></td></tr><tr><td>tal-linja</td><td>of the line</td><td>Contracted <code>ta&#39;</code> + <code>il-linja</code>; together &quot;the bus&quot;</td></tr></tbody></table><h3 id="_2" tabindex="-1">2. <a class="header-anchor" href="#_2" aria-label="Permalink to &quot;2.&quot;">​</a></h3><p><strong>Malti:</strong> Għandi liċenzja tas-sewqan tal-kategorija D.</p><p><strong>Translation:</strong> I hold a category D driving licence.</p><table><thead><tr><th>Maltese</th><th>English meaning</th><th>Notes</th></tr></thead><tbody><tr><td>Għandi</td><td>I have</td><td>First-person singular form of <code>għand</code></td></tr><tr><td>liċenzja</td><td>licence</td><td>Feminine loanword from licence</td></tr><tr><td>tas-sewqan</td><td>of driving</td><td>Contracted <code>ta&#39;</code> + <code>is-sewqan</code></td></tr><tr><td>tal-kategorija</td><td>of the category</td><td>Contracted <code>ta&#39;</code> + <code>il-kategorija</code></td></tr><tr><td>D</td><td>D (category)</td><td>Refers to the large-vehicle driving category</td></tr></tbody></table><h3 id="_3" tabindex="-1">3. <a class="header-anchor" href="#_3" aria-label="Permalink to &quot;3.&quot;">​</a></h3><p><strong>Malti:</strong> Għandi esperjenza ta&#39; tliet snin bħala sewwieq tal-karozza tal-linja.</p><p><strong>Translation:</strong> I have three years of experience as a bus driver.</p><table><thead><tr><th>Maltese</th><th>English meaning</th><th>Notes</th></tr></thead><tbody><tr><td>Għandi</td><td>I have</td><td>First-person singular form of <code>għand</code></td></tr><tr><td>esperjenza</td><td>experience</td><td>Feminine noun</td></tr><tr><td>ta&#39;</td><td>of</td><td>Possession linker</td></tr><tr><td>tliet</td><td>three</td><td>Numeral followed by a plural noun</td></tr><tr><td>snin</td><td>years</td><td>Plural of <code>sena</code></td></tr><tr><td>bħala</td><td>as</td><td>Preposition</td></tr><tr><td>sewwieq</td><td>driver</td><td>Masculine noun</td></tr><tr><td>tal-karozza tal-linja</td><td>of the bus</td><td>As above, &quot;the line&#39;s car&quot;</td></tr></tbody></table><h3 id="_4" tabindex="-1">4. <a class="header-anchor" href="#_4" aria-label="Permalink to &quot;4.&quot;">​</a></h3><p><strong>Malti:</strong> Naf it-toroq ta&#39; Malta tajjeb ħafna.</p><p><strong>Translation:</strong> I know the roads of Malta very well.</p><table><thead><tr><th>Maltese</th><th>English meaning</th><th>Notes</th></tr></thead><tbody><tr><td>Naf</td><td>I know; I am familiar with</td><td>First-person singular form</td></tr><tr><td>it-toroq</td><td>the roads</td><td>Plural of <code>triq</code>, with the definite article</td></tr><tr><td>ta&#39;</td><td>of</td><td>Possession linker</td></tr><tr><td>Malta</td><td>Malta</td><td>Place name</td></tr><tr><td>tajjeb</td><td>well</td><td>Used as an adverb here</td></tr><tr><td>ħafna</td><td>very</td><td>Adverb of degree</td></tr></tbody></table><h3 id="_5" tabindex="-1">5. <a class="header-anchor" href="#_5" aria-label="Permalink to &quot;5.&quot;">​</a></h3><p><strong>Malti:</strong> Jien responsabbli u jimpurtani mis-sigurtà tal-passiġġieri.</p><p><strong>Translation:</strong> I am responsible and I care about the safety of passengers.</p><table><thead><tr><th>Maltese</th><th>English meaning</th><th>Notes</th></tr></thead><tbody><tr><td>Jien</td><td>I</td><td>First-person singular pronoun</td></tr><tr><td>responsabbli</td><td>responsible</td><td>Adjective loanword from responsible</td></tr><tr><td>u</td><td>and</td><td>Conjunction</td></tr><tr><td>jimpurtani</td><td>I care</td><td><code>jimpurta</code> + <code>-ni</code> &quot;me&quot;; idiomatic expression</td></tr><tr><td>mis-sigurtà</td><td>about the safety</td><td>Contracted <code>minn</code> + <code>is-sigurtà</code></td></tr><tr><td>tal-passiġġieri</td><td>of the passengers</td><td>Contracted <code>ta&#39;</code> + <code>il-passiġġieri</code> (plural)</td></tr></tbody></table><h3 id="_6" tabindex="-1">6. <a class="header-anchor" href="#_6" aria-label="Permalink to &quot;6.&quot;">​</a></h3><p><strong>Malti:</strong> Ninsab kalm u paċenzjuż mat-traffiku.</p><p><strong>Translation:</strong> I stay calm and patient in traffic.</p><table><thead><tr><th>Maltese</th><th>English meaning</th><th>Notes</th></tr></thead><tbody><tr><td>Ninsab</td><td>I am; I remain</td><td>First-person singular form</td></tr><tr><td>kalm</td><td>calm</td><td>Adjective</td></tr><tr><td>u</td><td>and</td><td>Conjunction</td></tr><tr><td>paċenzjuż</td><td>patient</td><td>Adjective</td></tr><tr><td>mat-traffiku</td><td>with the traffic</td><td>Contracted <code>ma&#39;</code> + <code>it-traffiku</code></td></tr></tbody></table><h3 id="_7" tabindex="-1">7. <a class="header-anchor" href="#_7" aria-label="Permalink to &quot;7.&quot;">​</a></h3><p><strong>Malti:</strong> Nirrispetta r-regoli tat-triq u nżomm il-ħin.</p><p><strong>Translation:</strong> I respect the traffic rules and I am punctual.</p><table><thead><tr><th>Maltese</th><th>English meaning</th><th>Notes</th></tr></thead><tbody><tr><td>Nirrispetta</td><td>I respect; I obey</td><td>First-person singular form, loanword from respect</td></tr><tr><td>r-regoli</td><td>the rules</td><td>Plural of <code>regola</code>, with the definite article</td></tr><tr><td>tat-triq</td><td>of the road</td><td>Contracted <code>ta&#39;</code> + <code>it-triq</code>; i.e. &quot;traffic rules&quot;</td></tr><tr><td>u</td><td>and</td><td>Conjunction</td></tr><tr><td>nżomm</td><td>I keep; I maintain</td><td>First-person singular form</td></tr><tr><td>il-ħin</td><td>the time</td><td><code>nżomm il-ħin</code> is a fixed phrase meaning &quot;to be punctual&quot;</td></tr></tbody></table><h3 id="_8" tabindex="-1">8. <a class="header-anchor" href="#_8" aria-label="Permalink to &quot;8.&quot;">​</a></h3><p><strong>Malti:</strong> Nispera li nisma&#39; mingħandkom dalwaqt.</p><p><strong>Translation:</strong> I hope to hear from you soon.</p><table><thead><tr><th>Maltese</th><th>English meaning</th><th>Notes</th></tr></thead><tbody><tr><td>Nispera</td><td>I hope</td><td>First-person singular form</td></tr><tr><td>li</td><td>that; introduces a clause</td><td>Conjunction</td></tr><tr><td>nisma&#39;</td><td>I hear; receive news</td><td>First-person singular form</td></tr><tr><td>mingħandkom</td><td>from you (plural)</td><td><code>mingħand</code> + <code>-kom</code> &quot;you&quot;</td></tr><tr><td>dalwaqt</td><td>soon</td><td>Adverb</td></tr></tbody></table><h3 id="_9" tabindex="-1">9. <a class="header-anchor" href="#_9" aria-label="Permalink to &quot;9.&quot;">​</a></h3><p><strong>Malti:</strong> Grazzi talli qiesu l-applikazzjoni tiegħi.</p><p><strong>Translation:</strong> Thank you for considering my application.</p><table><thead><tr><th>Maltese</th><th>English meaning</th><th>Notes</th></tr></thead><tbody><tr><td>Grazzi</td><td>thank you</td><td>Polite phrase</td></tr><tr><td>talli</td><td>for (your) ...</td><td>Written expression introducing a reason</td></tr><tr><td>qiesu</td><td>they considered</td><td>Third-person plural past of <code>qies</code></td></tr><tr><td>l-applikazzjoni</td><td>the application</td><td>Feminine noun with the definite article</td></tr><tr><td>tiegħi</td><td>my; mine</td><td>Possessive pronoun</td></tr></tbody></table><p><strong>Malti:</strong> Tislijiet, [Ismek]</p><p><strong>Translation:</strong> Regards, [your name] (formal email closing).</p><table><thead><tr><th>Maltese</th><th>English meaning</th><th>Notes</th></tr></thead><tbody><tr><td>Tislijiet</td><td>regards; best wishes</td><td>Formal email/letter closing, literally &quot;greetings/regards&quot;</td></tr><tr><td>Ismek</td><td>your name</td><td><code>isem</code> &quot;name&quot; + <code>-ek</code> &quot;your&quot;; replace with your real name</td></tr></tbody></table>',61),i=[o];function n(s,l,h,p,c,u){return e(),a("div",null,i)}const b=t(r,[["render",n]]);export{g as __pageData,b as default};
